import{_ as l,B as s,o as c,c as d,a8 as u,a as t,E as n,f as a}from"./chunks/framework.CNIpabDg.js";const y=JSON.parse(`{"title":"WASM (executable)","description":"The WASM executable loads guest programs from Xila's VFS and runs them using Wasmi 2 with cooperative, resumable execution.","frontmatter":{"layout":"doc","docType":"explanation","description":"The WASM executable loads guest programs from Xila's VFS and runs them using Wasmi 2 with cooperative, resumable execution."},"headers":[],"relativePath":"explanation/architecture/executables/wasm.md","filePath":"explanation/architecture/executables/wasm.md","lastUpdated":1793145952000}`),p={name:"explanation/architecture/executables/wasm.md"};function h(m,e,g,b,f,x){const o=s("CodeReference"),i=s("HostReference"),r=s("GuestReference");return c(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[11]||(e[11]=u(`<h1 id="wasm-executable" tabindex="-1">WASM (executable) <a class="header-anchor" href="#wasm-executable" aria-label="Permalink to &quot;WASM (executable)&quot;">​</a></h1><p>The WASM executable loads guest programs from Xila&#39;s VFS and runs them using Wasmi 2. Both the native and browser examples mount it at <code>/applications/executables/wasm</code>.</p><h2 id="role-and-feature-selection" tabindex="-1">Role and feature selection <a class="header-anchor" href="#role-and-feature-selection" aria-label="Permalink to &quot;Role and feature selection&quot;">​</a></h2><p>The package serves two sides of the boundary: a host interpreter integrated with Xila&#39;s executable services, and helpers compiled into guest applications. The host role also applies when Xila runs in a browser. Optional graphics connects the interpreter to the context&#39;s graphics capability.</p><p>The <a href="/reference/wasm-runtime.html#cargo-features">runtime reference</a> defines the exact Cargo feature sets and defaults.</p><h2 id="launching-a-guest" tabindex="-1">Launching a guest <a class="header-anchor" href="#launching-a-guest" aria-label="Permalink to &quot;Launching a guest&quot;">​</a></h2><p>The launcher reads a guest from the VFS and invokes either its normal entrypoint or its installer. Both use typed, no-argument exports. Path handling belongs to the caller and the VFS; the loader does not implement the old <code>Current_directory</code> resolution step.</p><p>Follow <a href="/how-to/run-guest.html">Run a guest</a> for the procedure and <a href="/reference/wasm-runtime.html#command-syntax">command syntax</a> for its options and required exports.</p><h2 id="startup-and-lifecycle" tabindex="-1">Startup and lifecycle <a class="header-anchor" href="#startup-and-lifecycle" aria-label="Permalink to &quot;Startup and lifecycle&quot;">​</a></h2><ol><li>Parse the guest path, <code>--install</code>, <code>--stack-size</code>, and <code>--instruction-limit</code>.</li><li>Read bytes through the context-provided VFS and current task identifier.</li><li>Create a fresh Wasmi engine, module, linker, and store; there is no globally cached runtime.</li><li>Eagerly translate module functions before execution so fuel exhaustion cannot suspend lazy callee translation.</li><li>Bind standard streams, task environment, and the root directory preopen to the per-execution WASI context.</li><li>Register WASI and optional graphics imports, instantiate, and call the selected entrypoint resumably.</li><li>Yield on fuel exhaustion or supported suspension calls; report exit/trap errors and release VM-owned graphics objects.</li></ol><h2 id="runtime-integration-points" tabindex="-1">Runtime integration points <a class="header-anchor" href="#runtime-integration-points" aria-label="Permalink to &quot;Runtime integration points&quot;">​</a></h2><ul><li><code>ExecutableTrait</code>, <code>ExecutableContext</code>, and <code>Standard::context</code> for launch capabilities.</li><li>VFS <code>get_statistics</code> and <code>File::read_from_path</code> for module loading.</li><li>Wasmi <code>Engine</code>, <code>Module</code>, <code>Linker</code>, and <code>Store&lt;GlobalStore&gt;</code> for guest execution.</li><li>Local WASI descriptor tables for stdio and paths; guest imports do not use the removed <code>abi_context</code> crate.</li><li>Optional checked graphics adapters, including Xila-specific pointer/canvas helpers, use explicit per-VM graphics state rather than guest pointers to host objects.</li></ul><h2 id="failure-semantics-and-limits" tabindex="-1">Failure semantics and limits <a class="header-anchor" href="#failure-semantics-and-limits" aria-label="Permalink to &quot;Failure semantics and limits&quot;">​</a></h2><ul><li>Argument, file-kind, compilation, instantiation, missing-export, and execution failures are reported on stderr and return a nonzero executable result.</li><li>WASI <code>proc_exit(0)</code> succeeds; nonzero exit codes become runtime errors.</li><li>Wasmi 2 meters input Wasm operators. Fuel is replenished after cooperative yielding, so its quantum controls scheduling rather than a total instruction budget and is not a stable wall-time slice.</li><li>WASI coverage is partial; <code>poll_oneoff</code> supports clocks, not file-descriptor readiness. Start-section suspension is unsupported.</li><li>Graphical guests need bindings compatible with the host&#39;s LVGL revision/configuration and supported call subset.</li></ul><p>The native and browser examples now start from pre-seeded LittleFS images containing bundled WASI guests such as Calculator, Clock, Pixel Painter, Synth, Weather, and Text Editor. New images contain the matching applications and shortcuts; existing persistent images are preserved without automatic upgrades. The browser persists its selected live disk in OPFS. See <a href="/tutorials/browser.html">Browser tutorial</a> for the build flow, <a href="/explanation/browser-storage.html">Browser storage</a> for persistence, and <a href="/reference/container-runtime.html">the headless container runtime</a> for running WASI without graphics or networking.</p><p>Exact option defaults and constraints live in the <a href="/reference/wasm-runtime.html#execution-limits">runtime reference</a>.</p><h2 id="runner-command-and-guest-entrypoint-contract" tabindex="-1">Runner command and guest entrypoint contract <a class="header-anchor" href="#runner-command-and-guest-entrypoint-contract" aria-label="Permalink to &quot;Runner command and guest entrypoint contract&quot;">​</a></h2><p>The native <code>WasmExecutable</code> implements <code>ExecutableTrait</code> and normally runs as the mounted <code>/applications/executables/wasm</code> program. Its arguments are parsed by <code>getargs</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wasm /applications/executables/calculator</span></span>
<span class="line"><span>wasm --install /applications/executables/calculator</span></span>
<span class="line"><span>wasm --instruction-limit 50000 /applications/executables/clock</span></span>
<span class="line"><span>wasm /applications/executables/tool -- first-argument --guest-option</span></span></code></pre></div><p><code>--install</code> selects the typed <code>__install: () -&gt; ()</code> guest export rather than the normal <code>_start: () -&gt; ()</code>; installers are optional per application. A literal <code>--</code> separates runner options from guest arguments, which become WASI <code>argv</code> after the guest&#39;s path. <code>--help</code>/<code>--version</code> exit successfully; parsing errors return nonzero status.</p><p><code>--instruction-limit</code> defaults to <strong>100,000</strong> and must be a nonzero <code>u32</code>. It is a <strong>cooperative instruction quantum</strong>, not a total instruction budget or an execution timeout. <code>--stack-size</code> defaults to 4096 but is currently a <strong>legacy parsed option with no effect</strong>: the code explicitly discards its value and Wasmi manages stack allocation.</p><h2 id="per-execution-ownership-and-wasi-descriptors" tabindex="-1">Per-execution ownership and WASI descriptors <a class="header-anchor" href="#per-execution-ownership-and-wasi-descriptors" aria-label="Permalink to &quot;Per-execution ownership and WASI descriptors&quot;">​</a></h2><p>Each invocation creates a new Wasmi engine/module/linker/store; there is no shared module cache. The engine enables fuel consumption and <strong>eager</strong> translation, avoiding suspended execution during lazy callee compilation. The store embeds <code>GlobalStore</code> with a dedicated <code>WasiContext</code>, optional <code>GraphicsState</code>, the caller&#39;s <code>ExecutableContext</code>, and pending suspension state.</p><p>The guest receives <code>fd 0/1/2</code> from duplicated <code>Standard</code> streams. If opening the VFS root directory succeeds, it is preopened as <code>fd 3</code> with name <code>/</code>, and the next allocated descriptor is 4; otherwise the preopen is absent. Descriptor IDs increase monotonically and are not reused by <code>WasiContext</code> until a new execution.</p><p>The host registers a subset of WASI Preview 1: process/exit, environment/args, file/directory/path I/O, time, random, scheduling and clock-only <code>poll_oneoff</code>. This is <strong>not</strong> a complete POSIX or WASI implementation: arbitrary FD readiness, start-section yielding and unrestricted native graphics pointers remain unsupported.</p><h2 id="cooperative-suspension-time-and-exit-values" tabindex="-1">Cooperative suspension, time and exit values <a class="header-anchor" href="#cooperative-suspension-time-and-exit-values" aria-label="Permalink to &quot;Cooperative suspension, time and exit values&quot;">​</a></h2><p><code>execution::run</code> resumes a typed Wasmi call. On <code>OutOfFuel</code>, it yields to the Task scheduler, replenishes fuel to at least the amount needed by a single bulk operation, then resumes. Supported host suspension includes a yield import and clock-poll events; a pending clock poll sleeps in chunks capped at <strong>50 ms</strong> to check for shutdown and deadlines.</p><p>The monotonic WASI clock is sourced from <code>embassy_time::Instant</code>, <strong>not</strong> by subtracting Xila&#39;s adjustable signed UTC clock. This prevents wall-clock corrections from shifting monotonic poll deadlines. The system&#39;s UTC clock is adjustable and can be unsynchronized; invalid realtime returns a WASI clock error without aborting monotonic polling. The monotonic source is the same Embassy epoch used by the executor and is independent of wall-clock corrections.</p><p><code>proc_exit(0)</code> succeeds; positive guest exit statuses propagate, clamped to <strong>1–255</strong> at the external executable boundary. Module loading/validation, missing exports, instantiation and traps produce runtime errors. VM-local graphics state is reclaimed on teardown, including trap paths.</p><h2 id="build-modes-and-integration-testing" tabindex="-1">Build modes and integration testing <a class="header-anchor" href="#build-modes-and-integration-testing" aria-label="Permalink to &quot;Build modes and integration testing&quot;">​</a></h2><p>Cargo features distinguish <code>host</code> (Wasmi), <code>guest</code> (guest-side imports), optional <code>graphics</code>, <code>memory_32</code>/<code>memory_64</code>, and <code>c_bindings</code>/<code>default_guest</code>. The host runs on both native targets and inside the browser&#39;s <strong>host</strong> environment; being in the browser does not make host Wasmi code a guest.</p><p>Graphics calls are versioned with the LVGL configuration used to generate the bindings. Guest applications and reference disks must be rebuilt with matching host-side bindings after ABI changes.</p><h3 id="source-references" tabindex="-1">Source references <a class="header-anchor" href="#source-references" aria-label="Permalink to &quot;Source references&quot;">​</a></h3>`,33)),t("ul",null,[t("li",null,[n(o,{repo:"applications",path:"executables/wasm/src/host/main.rs"}),e[0]||(e[0]=a(" — options, modules and descriptor setup.",-1))]),t("li",null,[n(o,{repo:"applications",path:"executables/wasm/src/host/execution.rs"}),e[1]||(e[1]=a(" — resumable calls, fuel and clock polling.",-1))]),t("li",null,[n(o,{repo:"applications",path:"executables/wasm/src/host/wasi/context.rs"}),e[2]||(e[2]=a(" — descriptor table and ownership.",-1))]),t("li",null,[n(o,{repo:"applications",path:"executables/wasm/src/host/wasi/register.rs"}),e[3]||(e[3]=a(" — implemented WASI imports.",-1))]),t("li",null,[n(o,{repo:"applications",path:"executables/wasm/Cargo.toml"}),e[4]||(e[4]=a(" — host/guest/graphics feature gates.",-1))]),e[5]||(e[5]=t("li",null,[t("a",{href:"/explanation/architecture/executables/bindings.html"},"Graphics bindings"),a(" — checked guest UI boundary.")],-1))]),e[12]||(e[12]=t("h2",{id:"references",tabindex:"-1"},[a("References "),t("a",{class:"header-anchor",href:"#references","aria-label":'Permalink to "References"'},"​")],-1)),t("ul",null,[t("li",null,[n(i,{repo:"applications",crate:"wasm"}),e[6]||(e[6]=a(" — host-side interpreter and integration APIs.",-1))]),t("li",null,[n(r,{repo:"applications",crate:"wasm"}),e[7]||(e[7]=a(" — guest-facing WebAssembly helper APIs.",-1))]),t("li",null,[n(o,{repo:"applications",path:"executables/wasm"})]),e[8]||(e[8]=t("li",null,[t("p",null,[t("a",{href:"/reference/graphics-bindings.html"},"Graphics bindings")])],-1)),e[9]||(e[9]=t("li",null,[t("p",null,[t("a",{href:"/explanation/architecture/executables/bindings.html"},"Bindings")])],-1)),e[10]||(e[10]=t("li",null,[t("p",null,[t("a",{href:"/explanation/architecture/libraries/executable.html"},"Executable runtime crate")])],-1))])])}const v=l(p,[["render",h]]);export{y as __pageData,v as default};
